    Value -> {LDDLR[1,1] -> 0.1, LDDLR[2,2] -> 0.1, LDDLR[3,3] -> 0.1, LDDLR[i_, j_] :> 0 /; NumericQ[i] && NumericQ[j] && (i != j)},
