M$ClassesDescription = {
  S[100] == {
    ClassName -> six1,
    SelfConjugate -> False,
    Indices -> {Index[Sextet]},
    Mass -> {MSIX1, 500},
    Width -> {WSIX1, 4.4108},
    QuantumNumbers -> {Q -> 1/3, Y -> 1/3},
    ParticleName -> "six1",
    AntiParticleName -> "six1~",
    FullName -> "Scalar colour-sextet diquark six1, SU(2) singlet, Y=1/3",
    PropagatorLabel -> "six1",
    PropagatorType -> ScalarDash,
    PropagatorArrow -> None
  },
  S[200] == {
    ClassName -> six2,
    SelfConjugate -> False,
    Indices -> {Index[Sextet]},
    Mass -> {MSIX2, 500},
    Width -> {WSIX2, 4.7740},
    QuantumNumbers -> {Q -> -2/3, Y -> -2/3},
    ParticleName -> "six2",
    AntiParticleName -> "six2~",
    FullName -> "Scalar colour-sextet diquark six2, SU(2) singlet, Y=-2/3",
    PropagatorLabel -> "six2",
    PropagatorType -> ScalarDash,
    PropagatorArrow -> None
  },
  S[300] == {
    ClassName -> six3,
    SelfConjugate -> False,
    Indices -> {Index[Sextet]},
    Mass -> {MSIX3, 500},
    Width -> {WSIX3, 4.0647},
    QuantumNumbers -> {Q -> 4/3, Y -> 4/3},
    ParticleName -> "six3",
    AntiParticleName -> "six3~",
    FullName -> "Scalar colour-sextet diquark six3, SU(2) singlet, Y=4/3",
    PropagatorLabel -> "six3",
    PropagatorType -> ScalarDash,
    PropagatorArrow -> None
  }
};

LSextetKin := DC[six1bar[k], mu] DC[six1[k], mu] - MSIX1^2 six1bar[k] six1[k] + DC[six2bar[k], mu] DC[six2[k], mu] - MSIX2^2 six2bar[k] six2[k] + DC[six3bar[k], mu] DC[six3[k], mu] - MSIX3^2 six3bar[k] six3[k];

LD11 := 2 Sqrt[2] (K6bar[k, i, j] six1[k] LQQR[n, m] ProjP[s, r] dqbar[s, n, i].CC[uq][r, m, j] + K6bar[k, i, j] six1[k] LUDL[n, m] ProjM[s, r] dqbar[s, n, i].CC[uq][r, m, j]);

LD1 := LD11 + HC[LD11];

LD21 := 2 Sqrt[2] K6bar[k, i, j] six2[k] LDDL[n, m] ProjM[s, r] dqbar[s, n, i].CC[dq][r, m, j];

LD2 := LD21 + HC[LD21];

LD31 := 2 Sqrt[2] K6bar[k, i, j] six3[k] LUUL[n, m] ProjM[s, r] uqbar[s, n, i].CC[uq][r, m, j];

LD3 := LD31 + HC[LD31];

LD := LD1 + LD2 + LD3;

LPot := ExpandIndices[LHS1 Phibar[ii] Phi[ii] six1bar[k] six1[k] + LHS2 Phibar[ii] Phi[ii] six2bar[k] six2[k] + LHS3 Phibar[ii] Phi[ii] six3bar[k] six3[k] + LSS11 six1bar[k1] six1[k1] six1bar[k2] six1[k2] + LSS121 six1bar[k1] six1[k1] six2bar[k2] six2[k2] + LSS122 six1bar[k1] six1[k2] six2bar[k2] six2[k1] + LSS131 six1bar[k1] six1[k1] six3bar[k2] six3[k2] + LSS132 six1bar[k1] six1[k2] six3bar[k2] six3[k1] + LSS22 six2bar[k1] six2[k1] six2bar[k2] six2[k2] + LSS231 six2bar[k1] six2[k1] six3bar[k2] six3[k2] + LSS232 six2bar[k1] six2[k2] six3bar[k2] six3[k1] + LSS33 six3bar[k1] six3[k1] six3bar[k2] six3[k2], FlavorExpand -> {SU2W, SU2D}];

LSextet := LSextetKin + LD1 + LD2 + LD3 + LPot;

